package br.com.confirmacao;
import br.com.confirmacao.patient.domain.*;import br.com.confirmacao.patient.infrastructure.PatientRepository;import br.com.confirmacao.professional.domain.Professional;import br.com.confirmacao.professional.infrastructure.ProfessionalRepository;import br.com.confirmacao.scheduleblock.infrastructure.ScheduleBlockRepository;import br.com.confirmacao.session.application.*;import br.com.confirmacao.session.domain.*;import br.com.confirmacao.session.infrastructure.SessionAppointmentRepository;import jakarta.persistence.*;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class SessionSeriesServiceTest{@Test void createsFourWeeklySessionsOnlyWhenAllSlotsAreAvailable(){var sessions=mock(SessionAppointmentRepository.class);var patients=mock(PatientRepository.class);var professionals=mock(ProfessionalRepository.class);var blocks=mock(ScheduleBlockRepository.class);var entityManager=mock(EntityManager.class);var query=mock(Query.class);var professional=new Professional("Ana","ana@example.com","11999999999",null);var patient=new Patient(professional,"Paciente",null,"11888888888",null,PreferredContactChannel.WHATSAPP);var start=Instant.now().plus(Duration.ofDays(2));var end=start.plus(Duration.ofMinutes(50));when(professionals.findById(professional.getId())).thenReturn(Optional.of(professional));when(patients.findByIdAndProfessionalId(patient.getId(),professional.getId())).thenReturn(Optional.of(patient));when(entityManager.createNativeQuery(anyString())).thenReturn(query);when(query.setParameter(anyString(),any())).thenReturn(query);var service=new SessionSeriesService(sessions,patients,professionals,blocks,entityManager);var created=service.create(professional.getId(),patient.getId(),start,end,SessionModality.ONLINE,null,null);assertEquals(4,created.size());assertEquals(start.plus(Duration.ofDays(21)),created.get(3).getStartsAt());verify(sessions).saveAll(created);}@Test void savesNothingWhenAnyWeekConflicts(){var sessions=mock(SessionAppointmentRepository.class);var patients=mock(PatientRepository.class);var professionals=mock(ProfessionalRepository.class);var blocks=mock(ScheduleBlockRepository.class);var professional=new Professional("Ana","ana@example.com","11999999999",null);var patient=new Patient(professional,"Paciente",null,"11888888888",null,PreferredContactChannel.WHATSAPP);var start=Instant.now().plus(Duration.ofDays(2));var end=start.plus(Duration.ofMinutes(50));when(professionals.findById(professional.getId())).thenReturn(Optional.of(professional));when(patients.findByIdAndProfessionalId(patient.getId(),professional.getId())).thenReturn(Optional.of(patient));when(blocks.existsByProfessionalIdAndStartsAtLessThanAndEndsAtGreaterThan(any(),any(),any())).thenReturn(true);var service=new SessionSeriesService(sessions,patients,professionals,blocks,mock(EntityManager.class));assertThrows(SessionConflictException.class,()->service.create(professional.getId(),patient.getId(),start,end,SessionModality.ONLINE,null,null));verify(sessions,never()).saveAll(any());}@Test void preservesProfessionalLocalTimeAcrossOffsetChange(){
var sessions=mock(SessionAppointmentRepository.class);var patients=mock(PatientRepository.class);var professionals=mock(ProfessionalRepository.class);var blocks=mock(ScheduleBlockRepository.class);var em=mock(EntityManager.class);var query=mock(Query.class);
var professional=new Professional("Ana","timezone@example.com",null,null);professional.updateProfile("Ana","timezone@example.com",null,null,null,null,"America/New_York",50,"ONLINE",true);
var patient=new Patient(professional,"Paciente",null,"11999999999",null,PreferredContactChannel.WHATSAPP);var zone=ZoneId.of(professional.getTimezone());var transition=zone.getRules().nextTransition(Instant.now().plus(Duration.ofDays(10)));var local=transition.getInstant().atZone(zone).minusDays(5).withHour(9).withMinute(0).withSecond(0).withNano(0);var start=local.toInstant();
when(professionals.findById(professional.getId())).thenReturn(Optional.of(professional));when(patients.findByIdAndProfessionalId(patient.getId(),professional.getId())).thenReturn(Optional.of(patient));when(em.createNativeQuery(anyString())).thenReturn(query);when(query.setParameter(anyString(),any())).thenReturn(query);
var created=new SessionSeriesService(sessions,patients,professionals,blocks,em).create(professional.getId(),patient.getId(),start,start.plusSeconds(3000),SessionModality.ONLINE,null,null);
for(int week=0;week<4;week++){assertEquals(local.plusWeeks(week).toInstant(),created.get(week).getStartsAt());assertEquals(9,created.get(week).getStartsAt().atZone(zone).getHour());assertEquals(Duration.ofMinutes(50),Duration.between(created.get(week).getStartsAt(),created.get(week).getEndsAt()));}
assertNotEquals(Duration.ofDays(7),Duration.between(created.get(0).getStartsAt(),created.get(1).getStartsAt()));
}}
